                                        },
                                        MethodEndpoint::Route(route) => {
                                            let oneshot_future = route.0.clone().oneshot(req);
                                            let mut future = RouteFuture::from_future(oneshot_future);
                                            future = future.strip_body(strip_head);
                                            return future;
                                        }
                                        MethodEndpoint::BoxedHandler(handler) => {
                                            let boxed = handler.clone();
                                            let mut route = boxed.0.into_route(state);
                                            let oneshot_future = route.0.clone().oneshot(req);
                                            let mut future = RouteFuture::from_future(oneshot_future);
                                            future = future.strip_body(strip_head);
                                            return future;
